namespace HakutaiKagami.Core.Contracts;
public sealed record PresenceTerms(EntityId[] NpcFieldActors,EntityId ScenarioMover,FieldPoint A,FieldPoint B,string Source);
public sealed record FieldPresenceState(PresenceTerms Terms,EntityId[] DeployedActors);
public static class FieldPresence
{
    public const string Ruleset="created-retainer-continuous-presence-v1",Contract="independent-player-presence-npc-field-clock-static-sleep-exact-v1";
    public static bool Enabled(ContractWorld w)=>w.Definitions.Ruleset==Ruleset||DelegationMission.Enabled(w)||CareerMilitary.Enabled(w);
    public static PresenceTerms Terms=>new([ContractFixture.Clerk,RegionalBattle.Enemy],ContractFixture.Clerk,ContinuousWorld.Point("castle",195000,-85000),ContinuousWorld.Point("castle",305000,-85000),"scenario:independent-house-training-march");
    public static PresenceTerms ExpectedTerms(ContractWorld w)=>DelegationMission.Enabled(w)?new(Terms.NpcFieldActors,ContractFixture.Clerk,ContinuousWorld.Point("castle",95000,-50000),ContinuousWorld.Point("castle",115000,-30000),"scenario:joint-house-training-awaiting-orders"):Terms;
    public static bool Deployed(ContractWorld w,EntityId actor)=>Enabled(w)?w.Presence!.DeployedActors.Contains(actor):RegionalBattle.Active(w)&&w.Region!.Units.Any(u=>u.Commander==actor);
    public static bool PlayerDeployed(ContractWorld w)=>Enabled(w)?Deployed(w,w.PlayerControl):w.Region?.Active??false;
    public static ContractWorld Create(string name="作成武将",ulong seed=20261020){var w=FieldSupply.Create(name,seed);w.WorldId=new("world:"+Ruleset);w.Definitions=w.Definitions with{Id=new("scenario:"+Ruleset),Ruleset=Ruleset};w.Presence=new(Terms,Terms.NpcFieldActors.OrderBy(a=>a.Value,StringComparer.Ordinal).ToArray());w.Region=w.Region! with{Active=true,Since=0,Tick=0};RegionalBattle.ScenarioMove(w,Terms.ScenarioMover,Terms.A,Terms.B);w.Definitions=w.Definitions with{Version=RegionalBattle.Version(w)};RegionalBattle.Sync(w);ContractValidation.Validate(w);return w;}
    internal static void SetPlayer(ContractWorld w,bool active){if(!Enabled(w)||PlayerDeployed(w)==active)throw new InvalidDataException("No personal deployment transition");if(active){if(!w.Locations.Any(l=>l.Actor==w.PlayerControl&&l.Kind==LocationKind.AtSite&&l.Site==ContractFixture.Castle)||TravelWorld.Active(w))throw new InvalidDataException("本人の在所から出陣してください");}else{if(w.Region!.Units.Any(u=>u.Commander==w.PlayerControl&&(u.Position!=u.Home||u.Route.Any(l=>l.EndAt>w.ElapsedSeconds))))throw new InvalidDataException("本隊を帰還させてください");w.Locations=w.Locations.Select(l=>l.Actor==w.PlayerControl?new LocationState(l.Actor,LocationKind.AtSite,ContractFixture.Castle,null,0,0,null,null,null,null,w.CommitSequence):l).ToArray();}var ids=w.Presence!.DeployedActors.Where(id=>id!=w.PlayerControl);if(active)ids=ids.Append(w.PlayerControl);w.Presence=w.Presence with{DeployedActors=ids.OrderBy(id=>id.Value,StringComparer.Ordinal).ToArray()};}
    public static bool NeedsSecondSteps(ContractWorld w,long at)=>!Enabled(w)||w.Region!.Hostile||w.Region.Units.Any(u=>u.Route.Any(l=>l.EndAt>at))||TravelWorld.Active(w);
    public static void Validate(ContractWorld w){if(!Enabled(w))return;var p=w.Presence??throw new InvalidDataException("Missing independent presence");if(ContractJson.CanonicalHash(p.Terms)!=ContractJson.CanonicalHash(ExpectedTerms(w))||p.DeployedActors.Distinct().Count()!=p.DeployedActors.Length||!p.DeployedActors.SequenceEqual(p.DeployedActors.OrderBy(id=>id.Value,StringComparer.Ordinal))||Terms.NpcFieldActors.Any(id=>!p.DeployedActors.Contains(id))||p.DeployedActors.Any(id=>id!=w.PlayerControl&&!Terms.NpcFieldActors.Contains(id))||!w.Region!.Active)throw new InvalidDataException("Invalid field participant state");if(!PlayerDeployed(w)&&(w.Locations.Single(l=>l.Actor==w.PlayerControl).Kind==LocationKind.AtPosition||w.Region.Units.Any(u=>u.Commander==w.PlayerControl&&(u.Position!=u.Home||u.Route.Any(l=>l.EndAt>w.ElapsedSeconds)))))throw new InvalidDataException("Personal site state differs from force return");}
}
